package com.dtm.platform.service;
import com.dtm.platform.entity.*;import com.dtm.platform.repository.*;import com.dtm.platform.dto.*;import com.dtm.platform.mapper.*;import com.dtm.platform.exception.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import java.util.*;
@Service @Transactional public class ContentService {
 private final Map<String,ContentRepository<? extends ContentRecord>> repositories=new HashMap<>();
 private final Map<String,Class<? extends ContentRecord>> types=new HashMap<>();
 private final ContentMapper mapper;
 public ContentService(ContentMapper mapper,ProjectRepository projectsRepo,TechnologyRepository technologiesRepo,SkillRepository skillsRepo,ExperienceRepository experienceRepo,EducationRepository educationRepo,CompanyRepository companiesRepo,ServiceRepository servicesRepo,ArticleRepository articlesRepo,CategoryRepository categoriesRepo,ResumeRepository resumeRepo,TimelineEventRepository timelineRepo,ProfileRepository profileRepo,SettingRepository settingsRepo){this.mapper=mapper;repositories.put("projects",projectsRepo);types.put("projects",Project.class);repositories.put("technologies",technologiesRepo);types.put("technologies",Technology.class);repositories.put("skills",skillsRepo);types.put("skills",Skill.class);repositories.put("experience",experienceRepo);types.put("experience",Experience.class);repositories.put("education",educationRepo);types.put("education",Education.class);repositories.put("companies",companiesRepo);types.put("companies",Company.class);repositories.put("services",servicesRepo);types.put("services",com.dtm.platform.entity.Service.class);repositories.put("articles",articlesRepo);types.put("articles",Article.class);repositories.put("categories",categoriesRepo);types.put("categories",Category.class);repositories.put("resume",resumeRepo);types.put("resume",Resume.class);repositories.put("timeline",timelineRepo);types.put("timeline",TimelineEvent.class);repositories.put("profile",profileRepo);types.put("profile",Profile.class);repositories.put("settings",settingsRepo);types.put("settings",Setting.class);}
 public ContentRepository<? extends ContentRecord> repository(String resource){var r=repositories.get(resource);if(r==null)throw new ApiException(HttpStatus.NOT_FOUND,"Collection not found.");return r;}
 @SuppressWarnings("unchecked") private ContentRepository<ContentRecord> repo(String resource){return (ContentRepository<ContentRecord>)repository(resource);}
 public Set<String> resources(){return repositories.keySet();}
 @Transactional(readOnly=true) public PageDto<ContentDto> list(String resource,String q,String category,String status,int page,int size,String sort,boolean admin){
  if(!admin&&resource.equals("settings"))throw new ApiException(HttpStatus.NOT_FOUND,"Collection not found.");
  String[] parts=sort.split(",");String field=Set.of("name","createdAt","updatedAt","sortOrder").contains(parts[0])?parts[0]:"sortOrder";
  var direction=parts.length>1&&parts[1].equals("desc")?Sort.Direction.DESC:Sort.Direction.ASC;
  Specification<ContentRecord> spec=(root,query,cb)->{var predicates=new ArrayList<jakarta.persistence.criteria.Predicate>();if(!admin)predicates.add(cb.isTrue(root.get("published")));if(q!=null&&!q.isBlank()){String like="%"+q.toLowerCase(Locale.ROOT).replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%";predicates.add(cb.or(cb.like(cb.lower(root.get("name")),like,'\\'),cb.like(cb.lower(root.get("summary")),like,'\\')));}if(category!=null&&!category.isBlank())predicates.add(cb.equal(root.get("category"),category));if(status!=null&&!status.isBlank())predicates.add(cb.equal(root.get("status"),status));return cb.and(predicates.toArray(jakarta.persistence.criteria.Predicate[]::new));};
  var result=repo(resource).findAll(spec,PageRequest.of(Math.max(0,Math.min(page,10000)),Math.max(1,Math.min(size,100)),Sort.by(direction,field).and(Sort.by("id"))));
  return new PageDto<>(result.map(x->mapper.dto(resource,x)).getContent(),result.getTotalElements(),result.getNumber(),result.getSize(),result.getTotalPages());
 }
 public ContentRecord record(String resource,String key,boolean admin){ContentRecord row=key.matches("[0-9]+")?repo(resource).findById(Long.valueOf(key)).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Record not found.")):repo(resource).findBySlug(key).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Record not found."));if(!admin&&!row.published)throw new ApiException(HttpStatus.NOT_FOUND,"Record not found.");return row;}
 @Transactional(readOnly=true) public ContentDto detail(String resource,String key,boolean admin){return mapper.dto(resource,record(resource,key,admin));}
 public ContentDto save(String resource,String key,ContentInput input){
  ContentRecord row;if(key==null){try{row=types.get(resource).getDeclaredConstructor().newInstance();}catch(Exception e){throw new ApiException(HttpStatus.NOT_FOUND,"Collection not found.");}}else{row=record(resource,key,true);if(input.version()==null||!input.version().equals(row.version))throw new ApiException(HttpStatus.CONFLICT,"The record changed. Reload before saving.");}
  com.dtm.platform.validation.ContentDataValidator.validate(resource,input.data());mapper.apply(row,input);repo(resource).saveAndFlush(row);
  if(row instanceof Project project){syncTechnologies(project,input.data());Object company=input.data()==null?null:input.data().get("companySlug");if(company instanceof String slug)project.company=(Company)record("companies",slug,true);}
  if(row instanceof Resume resume){Object mediaId=input.data()==null?null:input.data().get("mediaId");if(mediaId instanceof Number id){resume.media=mediaRepository.findById(id.longValue()).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Media does not exist."));if(!"application/pdf".equals(resume.media.contentType))throw new ApiException(HttpStatus.BAD_REQUEST,"Resume versions require a PDF.");}}
  repo(resource).flush();return mapper.dto(resource,row);
 }
 @org.springframework.beans.factory.annotation.Autowired private MediaRepository mediaRepository;
 private void syncTechnologies(Project project,Map<String,Object> data){if(data==null||!(data.get("technologies") instanceof List<?> names)){project.technologies.clear();return;}var technologies=new java.util.LinkedHashMap<Long,Technology>();for(Object name:names){var technology=repo("technologies").findBySlug(slug(String.valueOf(name)));if(technology.isPresent())technologies.put(technology.get().id,(Technology)technology.get());}project.technologies.removeIf(link->!technologies.containsKey(link.technology.id));var current=project.technologies.stream().map(link->link.technology.id).collect(java.util.stream.Collectors.toSet());for(var technology:technologies.values())if(!current.contains(technology.id)){var link=new ProjectTechnology();link.project=project;link.technology=technology;project.technologies.add(link);}}
 public static String slug(String name){return name.equals("C++")?"cpp":name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");}
 public void delete(String resource,String key){repo(resource).delete(record(resource,key,true));}
 @Transactional(readOnly=true) public List<ContentDto> search(String query){if(query==null||query.isBlank())return List.of();var result=new ArrayList<ContentDto>();for(String resource:List.of("projects","technologies","skills","experience","articles","services"))result.addAll(list(resource,query,null,null,0,8,"sortOrder,asc",false).items());return result;}
}
